(() => {
  const state = {
    orders: [], products: [], services: [], serviceOrders: [], banners: [], settings: null,
    orderSearch: '', orderStatus: 'all', serviceTab: 'orders', serviceSearch: '', serviceStatus: 'all',
    offerSearch: '', bannerSearch: ''
  };

  const api = () => window.BLACKOUT_ADMIN;
  const content = () => document.querySelector('#admin-content');
  const escapeHtml = value => api().escapeHtml(value);
  const money = value => api().money(value);
  const dateTime = value => api().dateTime(value);
  const phoneDigits = value => String(value || '').replace(/\D/g, '');
  const assetUrl = value => {
    if (!value) return '';
    const url = String(value);
    if (/^(https?:|data:|blob:)/i.test(url)) return url;
    const base = String(window.BLACKOUT_PUBLIC_SITE_URL || '').replace(/\/$/, '');
    return base ? `${base}/${url.replace(/^\.\//, '')}` : `/${url.replace(/^\.\//, '')}`;
  };
  const orderStatuses = [
    ['recebido','Recebido'],['aguardando_pagamento','Aguardando pagamento'],['pago','Pago'],
    ['em_preparacao','Em preparação'],['pronto','Pronto'],['concluido','Concluído'],['cancelado','Cancelado']
  ];
  const serviceStatuses = [
    ['recebido','Recebido'],['diagnostico','Em diagnóstico'],['aguardando_aprovacao','Aguardando aprovação'],
    ['em_reparo','Em reparo'],['pronto','Pronto'],['entregue','Entregue'],['cancelado','Cancelado']
  ];

  function statusLabel(value, source = orderStatuses) {
    return source.find(item => item[0] === value)?.[1] || String(value || 'Não informado').replaceAll('_', ' ');
  }
  function statusOptions(selected, source = orderStatuses) {
    return source.map(([value,label]) => `<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('');
  }
  function moduleSkeleton(title) {
    return `<div class="module-head"><div><h2>${title}</h2><p>Carregando dados do Supabase…</p></div></div><div class="catalog-stats">${Array.from({length:4},()=>'<div class="catalog-stat skeleton"><div class="skeleton-line"></div><div class="skeleton-line big"></div></div>').join('')}</div><section class="admin-card catalog-panel skeleton">${Array.from({length:7},()=>'<div class="skeleton-line"></div>').join('')}</section>`;
  }
  function moduleError(title, message, retry, migration = false) {
    content().innerHTML = `<section class="admin-card module-placeholder"><span>!</span><h2>${escapeHtml(title)}</h2><p>${escapeHtml(message)}</p>${migration?'<small class="migration-note">Execute a migração <strong>admin-004-operations-management.sql</strong> no Supabase para ativar este módulo.</small>':''}<button class="admin-primary" id="operations-retry" style="max-width:240px;margin:18px auto 0">Tentar novamente</button></section>`;
    document.querySelector('#operations-retry').onclick = retry;
  }
  function openDialog(markup, onSubmit) {
    const dialog = document.createElement('dialog');
    dialog.className = 'admin-dialog';
    dialog.innerHTML = markup;
    document.body.appendChild(dialog);
    const close = () => { dialog.close(); dialog.remove(); };
    dialog.querySelector('.dialog-close').onclick = close;
    dialog.querySelector('.dialog-cancel')?.addEventListener('click', close);
    dialog.addEventListener('cancel', event => { event.preventDefault(); close(); });
    if (onSubmit) dialog.querySelector('form').onsubmit = event => onSubmit(event, close);
    dialog.showModal();
    return dialog;
  }
  async function fetchOrders() {
    const rows = await api().request('/rest/v1/orders?select=*&order=created_at.desc');
    state.orders = Array.isArray(rows) ? rows : [];
    return state.orders;
  }
  async function fetchProducts() {
    const rows = await api().request('/rest/v1/products?select=*&order=name.asc');
    state.products = Array.isArray(rows) ? rows : [];
    return state.products;
  }

  function filteredOrders() {
    const needle = state.orderSearch.trim().toLocaleLowerCase('pt-BR');
    return state.orders.filter(order => {
      const matchesSearch = !needle || [order.id, order.customer_name, order.customer_email, order.customer_phone].some(value => String(value || '').toLocaleLowerCase('pt-BR').includes(needle));
      return matchesSearch && (state.orderStatus === 'all' || order.status === state.orderStatus);
    });
  }
  function orderItems(order) {
    if (!Array.isArray(order.items)) return [];
    return order.items.map(item => ({name:item.name || 'Produto', quantity:Number(item.quantity || 1), unit_price:Number(item.unit_price || 0)}));
  }
  function renderOrders() {
    const rows = filteredOrders();
    const pending = state.orders.filter(order => !['concluido','cancelado'].includes(order.status)).length;
    const paid = state.orders.filter(order => ['pago','em_preparacao','pronto','concluido'].includes(order.status));
    const revenue = paid.reduce((sum,order) => sum + Number(order.total || 0), 0);
    content().innerHTML = `<div class="module-head"><div><span class="module-kicker">VENDAS</span><h2>Pedidos</h2><p>Acompanhe pagamentos, preparação e entrega em uma única fila.</p></div><button class="admin-primary compact" id="new-order">＋ Novo pedido</button></div>
      <div class="catalog-stats"><article class="catalog-stat"><small>TOTAL</small><strong>${state.orders.length}</strong><span>pedidos registrados</span></article><article class="catalog-stat ${pending?'warning':''}"><small>EM ANDAMENTO</small><strong>${pending}</strong><span>aguardam conclusão</span></article><article class="catalog-stat"><small>PAGOS</small><strong>${paid.length}</strong><span>confirmados</span></article><article class="catalog-stat"><small>FATURAMENTO</small><strong>${money(revenue)}</strong><span>pedidos confirmados</span></article></div>
      <section class="admin-card catalog-panel"><div class="catalog-toolbar operations-toolbar"><label class="search-control"><span>⌕</span><input id="order-search" type="search" placeholder="Buscar pedido, cliente ou telefone" value="${escapeHtml(state.orderSearch)}"></label><select id="order-status"><option value="all">Todos os status</option>${statusOptions(state.orderStatus)}</select><span class="result-count">${rows.length} pedido${rows.length===1?'':'s'}</span></div>
      ${rows.length?`<div class="catalog-table-wrap"><table class="catalog-table operations-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pagamento</th><th>Status</th><th>Data</th><th>Ações</th></tr></thead><tbody>${rows.map(order=>`<tr><td><strong>#${escapeHtml(order.id)}</strong><small class="table-sub">${orderItems(order).length} item${orderItems(order).length===1?'':'s'}</small></td><td><strong>${escapeHtml(order.customer_name)}</strong><small class="table-sub">${escapeHtml(order.customer_phone||order.customer_email||'Sem contato')}</small></td><td><strong>${money(order.total)}</strong></td><td>${escapeHtml(order.payment_method||'Não informado')}</td><td><select class="status-select status-${escapeHtml(order.status)}" data-order-status="${order.id}">${statusOptions(order.status)}</select></td><td>${dateTime(order.created_at)}</td><td><button class="table-action" data-order-view="${order.id}">Detalhes</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state rich-empty"><span>▤</span><strong>Nenhum pedido encontrado</strong><p>Ajuste os filtros ou registre uma venda manual.</p></div>'}</section>`;
    document.querySelector('#new-order').onclick = () => window.BLACKOUT_ADMIN_MANUAL.openDialog(() => loadOrders(true));
    document.querySelector('#order-search').oninput = event => { state.orderSearch=event.target.value;renderOrders();document.querySelector('#order-search')?.focus(); };
    document.querySelector('#order-status').onchange = event => { state.orderStatus=event.target.value;renderOrders(); };
    document.querySelectorAll('[data-order-view]').forEach(button => button.onclick=()=>openOrderDetails(String(button.dataset.orderView)));
    document.querySelectorAll('[data-order-status]').forEach(select => select.onchange=()=>updateOrderStatus(select.dataset.orderStatus,select.value,select));
  }
  async function updateOrderStatus(id, status, select) {
    select.disabled=true;
    try { await api().request(`/rest/v1/orders?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{status},headers:{Prefer:'return=minimal'}}); const order=state.orders.find(item=>String(item.id)===String(id));if(order)order.status=status;renderOrders();api().toast('Status do pedido atualizado'); }
    catch { select.disabled=false;api().toast('Não foi possível atualizar o pedido'); }
  }
  function openOrderDetails(id) {
    const order=state.orders.find(item=>String(item.id)===String(id));if(!order)return;
    const items=orderItems(order);
    const contact=phoneDigits(order.customer_phone);
    openDialog(`<section class="entity-form"><div class="dialog-head"><div><span class="module-kicker">PEDIDO #${escapeHtml(order.id)}</span><h2>${escapeHtml(order.customer_name)}</h2></div><button type="button" class="dialog-close" aria-label="Fechar">×</button></div><div class="detail-grid"><article><small>CONTATO</small><strong>${escapeHtml(order.customer_phone||'Sem telefone')}</strong><span>${escapeHtml(order.customer_email||'Sem e-mail')}</span></article><article><small>TOTAL</small><strong>${money(order.total)}</strong><span>${escapeHtml(order.payment_method||'Pagamento não informado')}</span></article><article><small>STATUS</small><strong>${escapeHtml(statusLabel(order.status))}</strong><span>${dateTime(order.created_at)}</span></article></div><div class="dialog-section"><h3>Itens do pedido</h3>${items.length?`<div class="item-list">${items.map(item=>`<div><span>${item.quantity}× ${escapeHtml(item.name)}</span><strong>${money(item.unit_price*item.quantity)}</strong></div>`).join('')}</div>`:'<p class="muted-copy">Pedido manual sem itens detalhados.</p>'}</div>${order.admin_notes?`<div class="dialog-section"><h3>Observações internas</h3><p class="muted-copy">${escapeHtml(order.admin_notes)}</p></div>`:''}<div class="dialog-actions"><button type="button" class="secondary-action dialog-cancel">Fechar</button>${contact?`<a class="admin-primary compact action-link" href="https://wa.me/55${contact}" target="_blank" rel="noopener">Falar no WhatsApp</a>`:''}</div></section>`);
  }
  async function loadOrders(force=false){content().innerHTML=moduleSkeleton('PEDIDOS');try{await fetchOrders();renderOrders();if(force)api().toast('Pedidos atualizados');}catch{moduleError('PEDIDOS INDISPONÍVEIS','Não foi possível carregar os pedidos.',()=>loadOrders(true));}}

  function customersFromOrders(){
    const map=new Map();
    state.orders.forEach(order=>{const key=String(order.customer_email||order.customer_phone||order.customer_name||order.id).toLocaleLowerCase('pt-BR');if(!map.has(key))map.set(key,{name:order.customer_name,email:order.customer_email,phone:order.customer_phone,orders:[],total:0,last:null});const customer=map.get(key);customer.orders.push(order);customer.total+=Number(order.total||0);if(!customer.last||new Date(order.created_at)>new Date(customer.last))customer.last=order.created_at;});
    return [...map.values()].sort((a,b)=>new Date(b.last)-new Date(a.last));
  }
  function renderCustomers(){
    const all=customersFromOrders();const needle=state.orderSearch.trim().toLocaleLowerCase('pt-BR');const customers=all.filter(customer=>!needle||[customer.name,customer.email,customer.phone].some(value=>String(value||'').toLocaleLowerCase('pt-BR').includes(needle)));const recurring=all.filter(customer=>customer.orders.length>1).length;const total=all.reduce((sum,customer)=>sum+customer.total,0);
    content().innerHTML=`<div class="module-head"><div><span class="module-kicker">RELACIONAMENTO</span><h2>Clientes</h2><p>Histórico e contatos consolidados automaticamente pelos pedidos.</p></div><button class="secondary-action" id="customers-orders">Ver pedidos</button></div><div class="catalog-stats category-stats"><article class="catalog-stat"><small>CLIENTES</small><strong>${all.length}</strong><span>contatos únicos</span></article><article class="catalog-stat"><small>RECORRENTES</small><strong>${recurring}</strong><span>compraram mais de uma vez</span></article><article class="catalog-stat"><small>VALOR GERADO</small><strong>${money(total)}</strong><span>em pedidos registrados</span></article></div><section class="admin-card catalog-panel"><div class="catalog-toolbar customers-toolbar"><label class="search-control"><span>⌕</span><input id="customer-search" type="search" placeholder="Buscar nome, telefone ou e-mail" value="${escapeHtml(state.orderSearch)}"></label><span class="result-count">${customers.length} cliente${customers.length===1?'':'s'}</span></div>${customers.length?`<div class="catalog-table-wrap"><table class="catalog-table customers-table"><thead><tr><th>Cliente</th><th>Contato</th><th>Pedidos</th><th>Total comprado</th><th>Última compra</th><th>Ações</th></tr></thead><tbody>${customers.map((customer,index)=>`<tr><td><strong>${escapeHtml(customer.name)}</strong></td><td>${escapeHtml(customer.phone||customer.email||'Sem contato')}</td><td>${customer.orders.length}</td><td><strong>${money(customer.total)}</strong></td><td>${dateTime(customer.last)}</td><td><button class="table-action" data-customer-view="${index}">Histórico</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state rich-empty"><span>♙</span><strong>Nenhum cliente encontrado</strong><p>Os clientes aparecem automaticamente quando recebem pedidos.</p></div>'}</section>`;
    document.querySelector('#customers-orders').onclick=()=>api().selectView('orders');document.querySelector('#customer-search').oninput=event=>{state.orderSearch=event.target.value;renderCustomers();document.querySelector('#customer-search')?.focus();};document.querySelectorAll('[data-customer-view]').forEach(button=>button.onclick=()=>openCustomerDetails(customers[Number(button.dataset.customerView)]));
  }
  function openCustomerDetails(customer){const contact=phoneDigits(customer.phone);openDialog(`<section class="entity-form"><div class="dialog-head"><div><span class="module-kicker">CLIENTE</span><h2>${escapeHtml(customer.name)}</h2></div><button type="button" class="dialog-close">×</button></div><div class="detail-grid"><article><small>TELEFONE</small><strong>${escapeHtml(customer.phone||'Não informado')}</strong><span>${escapeHtml(customer.email||'E-mail não informado')}</span></article><article><small>PEDIDOS</small><strong>${customer.orders.length}</strong><span>registrados</span></article><article><small>TOTAL</small><strong>${money(customer.total)}</strong><span>em compras</span></article></div><div class="dialog-section"><h3>Histórico</h3><div class="item-list">${customer.orders.map(order=>`<div><span>#${escapeHtml(order.id)} • ${escapeHtml(statusLabel(order.status))}</span><strong>${money(order.total)}</strong></div>`).join('')}</div></div><div class="dialog-actions"><button type="button" class="secondary-action dialog-cancel">Fechar</button>${contact?`<a class="admin-primary compact action-link" href="https://wa.me/55${contact}" target="_blank" rel="noopener">WhatsApp</a>`:''}</div></section>`);}
  async function loadCustomers(force=false){content().innerHTML=moduleSkeleton('CLIENTES');try{await fetchOrders();renderCustomers();if(force)api().toast('Clientes atualizados');}catch{moduleError('CLIENTES INDISPONÍVEIS','Não foi possível consolidar os clientes.',()=>loadCustomers(true));}}

  async function fetchServices(){const rows=await api().request('/rest/v1/services?select=*&order=sort_order.asc,name.asc');state.services=Array.isArray(rows)?rows:[];return state.services;}
  async function fetchServiceOrders(){const rows=await api().request('/rest/v1/service_orders?select=*,services(name)&order=created_at.desc');state.serviceOrders=Array.isArray(rows)?rows:[];return state.serviceOrders;}
  function renderServices(){
    const active=state.services.filter(item=>item.active).length;const open=state.serviceOrders.filter(item=>!['entregue','cancelado'].includes(item.status)).length;const ready=state.serviceOrders.filter(item=>item.status==='pronto').length;const revenue=state.serviceOrders.filter(item=>item.status==='entregue').reduce((sum,item)=>sum+Number(item.final_price||item.estimate||0),0);
    content().innerHTML=`<div class="module-head"><div><span class="module-kicker">ASSISTÊNCIA TÉCNICA</span><h2>Serviços</h2><p>Gerencie o catálogo de serviços e cada equipamento em atendimento.</p></div><button class="admin-primary compact" id="new-service-action">＋ ${state.serviceTab==='orders'?'Nova ordem':'Novo serviço'}</button></div><div class="catalog-stats"><article class="catalog-stat"><small>SERVIÇOS ATIVOS</small><strong>${active}</strong><span>disponíveis</span></article><article class="catalog-stat ${open?'warning':''}"><small>EM ANDAMENTO</small><strong>${open}</strong><span>ordens abertas</span></article><article class="catalog-stat"><small>PRONTOS</small><strong>${ready}</strong><span>aguardam retirada</span></article><article class="catalog-stat"><small>RECEITA TÉCNICA</small><strong>${money(revenue)}</strong><span>ordens entregues</span></article></div><div class="module-tabs"><button data-service-tab="orders" class="${state.serviceTab==='orders'?'active':''}">Ordens técnicas</button><button data-service-tab="catalog" class="${state.serviceTab==='catalog'?'active':''}">Catálogo de serviços</button></div>${state.serviceTab==='orders'?serviceOrdersMarkup():serviceCatalogMarkup()}`;
    document.querySelectorAll('[data-service-tab]').forEach(button=>button.onclick=()=>{state.serviceTab=button.dataset.serviceTab;renderServices();});document.querySelector('#new-service-action').onclick=()=>state.serviceTab==='orders'?openServiceOrderDialog():openServiceDialog();bindServiceRows();
  }
  function serviceOrdersMarkup(){const needle=state.serviceSearch.trim().toLocaleLowerCase('pt-BR');const rows=state.serviceOrders.filter(item=>(state.serviceStatus==='all'||item.status===state.serviceStatus)&&(!needle||[item.customer_name,item.customer_phone,item.device,item.issue,item.services?.name].some(value=>String(value||'').toLocaleLowerCase('pt-BR').includes(needle))));return `<section class="admin-card catalog-panel"><div class="catalog-toolbar operations-toolbar"><label class="search-control"><span>⌕</span><input id="service-search" type="search" placeholder="Buscar cliente, aparelho ou defeito" value="${escapeHtml(state.serviceSearch)}"></label><select id="service-status"><option value="all">Todos os status</option>${statusOptions(state.serviceStatus,serviceStatuses)}</select><span class="result-count">${rows.length} ${rows.length===1?'ordem':'ordens'}</span></div>${rows.length?`<div class="catalog-table-wrap"><table class="catalog-table operations-table"><thead><tr><th>OS</th><th>Cliente</th><th>Equipamento</th><th>Serviço</th><th>Previsão</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(item=>`<tr><td><strong>#${item.id}</strong></td><td><strong>${escapeHtml(item.customer_name)}</strong><small class="table-sub">${escapeHtml(item.customer_phone||'Sem telefone')}</small></td><td>${escapeHtml(item.device)}</td><td>${escapeHtml(item.services?.name||'Avaliação técnica')}</td><td>${item.due_date?new Date(item.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'A definir'}</td><td><select class="status-select" data-service-order-status="${item.id}">${statusOptions(item.status,serviceStatuses)}</select></td><td><button class="table-action" data-service-order-view="${item.id}">Detalhes</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state rich-empty"><span>⚙</span><strong>Nenhuma ordem técnica</strong><p>Registre o primeiro atendimento para acompanhar o serviço.</p></div>'}</section>`;}
  function servicePriceSummary(item){if(item.price_type==='sale')return `${money(item.old_price)} → ${money(item.promotional_price)}`;if(item.price_type==='starting_at')return `A partir de ${money(item.starting_price)}`;if(item.price_type==='consult')return 'Preço sob consulta';return money(item.price);}
  function serviceCatalogMarkup(){return `<section class="admin-card catalog-panel">${state.services.length?`<div class="service-admin-grid">${state.services.map(item=>`<article class="service-admin-card"><div class="service-admin-thumb">${item.image_url?`<img src="${escapeHtml(assetUrl(item.image_url))}" alt="">`:`<span>${escapeHtml(item.icon||'⚙')}</span>`}</div><div><small>${item.active?'ATIVO':'INATIVO'} • ORDEM ${Number(item.sort_order||0)}</small><h3>${escapeHtml(item.name)}${item.model?` <em>${escapeHtml(item.model)}</em>`:''}</h3><p>${escapeHtml(item.description||'Sem descrição')}</p><strong>${escapeHtml(servicePriceSummary(item))}${item.duration_label?` • ${escapeHtml(item.duration_label)}`:''}</strong></div><div class="service-card-actions"><button class="visibility-toggle ${item.active?'on':''}" data-service-toggle="${item.id}"><span></span>${item.active?'Ativo':'Inativo'}</button><button class="table-action" data-service-edit="${item.id}">Editar</button><button class="table-action danger" data-service-delete="${item.id}">Excluir</button></div></article>`).join('')}</div>`:'<div class="empty-state rich-empty"><span>⚙</span><strong>Nenhum serviço cadastrado</strong><p>Cadastre os serviços oferecidos pela assistência técnica.</p></div>'}</section>`;}
  function bindServiceRows(){document.querySelector('#service-search')?.addEventListener('input',event=>{state.serviceSearch=event.target.value;renderServices();document.querySelector('#service-search')?.focus();});document.querySelector('#service-status')?.addEventListener('change',event=>{state.serviceStatus=event.target.value;renderServices();});document.querySelectorAll('[data-service-order-status]').forEach(select=>select.onchange=()=>updateServiceOrderStatus(select.dataset.serviceOrderStatus,select.value,select));document.querySelectorAll('[data-service-order-view]').forEach(button=>button.onclick=()=>openServiceOrderDetails(Number(button.dataset.serviceOrderView)));document.querySelectorAll('[data-service-edit]').forEach(button=>button.onclick=()=>openServiceDialog(Number(button.dataset.serviceEdit)));document.querySelectorAll('[data-service-toggle]').forEach(button=>button.onclick=()=>toggleService(Number(button.dataset.serviceToggle),button));document.querySelectorAll('[data-service-delete]').forEach(button=>button.onclick=()=>deleteService(Number(button.dataset.serviceDelete),button));}
  async function updateServiceOrderStatus(id,status,select){select.disabled=true;try{await api().request(`/rest/v1/service_orders?id=eq.${id}`,{method:'PATCH',body:{status},headers:{Prefer:'return=minimal'}});const item=state.serviceOrders.find(row=>Number(row.id)===Number(id));if(item)item.status=status;renderServices();api().toast('Ordem técnica atualizada');}catch{select.disabled=false;api().toast('Não foi possível atualizar a ordem');}}
  function openServiceOrderDetails(id){const item=state.serviceOrders.find(row=>Number(row.id)===id);if(!item)return;const contact=phoneDigits(item.customer_phone);openDialog(`<section class="entity-form"><div class="dialog-head"><div><span class="module-kicker">ORDEM #${item.id}</span><h2>${escapeHtml(item.device)}</h2></div><button type="button" class="dialog-close">×</button></div><div class="detail-grid"><article><small>CLIENTE</small><strong>${escapeHtml(item.customer_name)}</strong><span>${escapeHtml(item.customer_phone||'Sem telefone')}</span></article><article><small>SERVIÇO</small><strong>${escapeHtml(item.services?.name||'Avaliação')}</strong><span>${money(item.final_price||item.estimate||0)}</span></article><article><small>STATUS</small><strong>${escapeHtml(statusLabel(item.status,serviceStatuses))}</strong><span>${dateTime(item.created_at)}</span></article></div><div class="dialog-section"><h3>Relato</h3><p class="muted-copy">${escapeHtml(item.issue||'Sem descrição do defeito.')}</p></div>${item.technical_notes?`<div class="dialog-section"><h3>Notas técnicas</h3><p class="muted-copy">${escapeHtml(item.technical_notes)}</p></div>`:''}<div class="dialog-actions"><button type="button" class="secondary-action dialog-cancel">Fechar</button>${contact?`<a class="admin-primary compact action-link" target="_blank" rel="noopener" href="https://wa.me/55${contact}">Avisar cliente</a>`:''}</div></section>`);}
  function openServiceOrderDialog(){openDialog(`<form class="entity-form"><div class="dialog-head"><div><span class="module-kicker">ASSISTÊNCIA</span><h2>Nova ordem técnica</h2></div><button type="button" class="dialog-close">×</button></div><div class="form-grid"><label class="field"><span>Cliente</span><input name="customer_name" required></label><label class="field"><span>Telefone</span><input name="customer_phone" required></label><label class="field"><span>Equipamento</span><input name="device" placeholder="Console, PC, controle…" required></label><label class="field"><span>Serviço</span><select name="service_id"><option value="">Avaliação técnica</option>${state.services.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('')}</select></label><label class="field wide"><span>Defeito relatado</span><textarea name="issue" rows="3" required></textarea></label><label class="field"><span>Orçamento</span><input name="estimate" type="number" min="0" step="0.01"></label><label class="field"><span>Previsão</span><input name="due_date" type="date"></label><label class="field"><span>Status</span><select name="status">${statusOptions('recebido',serviceStatuses)}</select></label><label class="field wide"><span>Notas técnicas</span><textarea name="technical_notes" rows="3"></textarea></label></div><div class="form-error"></div><div class="dialog-actions"><button type="button" class="secondary-action dialog-cancel">Cancelar</button><button type="submit" class="admin-primary compact">Criar ordem</button></div></form>`,saveServiceOrder);}
  async function saveServiceOrder(event,close){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const button=form.querySelector('[type="submit"]');const payload={customer_name:data.get('customer_name').trim(),customer_phone:data.get('customer_phone').trim(),device:data.get('device').trim(),service_id:data.get('service_id')?Number(data.get('service_id')):null,issue:data.get('issue').trim(),estimate:Number(data.get('estimate')||0),due_date:data.get('due_date')||null,status:data.get('status'),technical_notes:data.get('technical_notes').trim()||null};button.disabled=true;try{await api().request('/rest/v1/service_orders',{method:'POST',body:payload,headers:{Prefer:'return=minimal'}});close();await loadServices(true);api().toast('Ordem técnica criada');}catch{form.querySelector('.form-error').textContent='Não foi possível criar a ordem técnica.';form.querySelector('.form-error').classList.add('show');button.disabled=false;}}
  function openServiceDialog(id=null){
    const item=id?state.services.find(row=>Number(row.id)===id):null;
    const type=item?.price_type||'normal';
    const benefits=Array.isArray(item?.benefits)?item.benefits.join('\n'):'';
    const dialog=openDialog(`<form class='entity-form'><div class='dialog-head'><div><span class='module-kicker'>SERVIÇO</span><h2>${item?'Editar serviço':'Novo serviço'}</h2></div><button type='button' class='dialog-close'>×</button></div><div class='form-grid'><label class='field'><span>Título</span><input name='name' value='${escapeHtml(item?.name||'')}' required></label><label class='field'><span>Modelo / subtítulo</span><input name='model' value='${escapeHtml(item?.model||'')}' placeholder='Ex.: PS4'></label><label class='field wide'><span>Imagem (URL ou caminho)</span><input name='image_url' value='${escapeHtml(item?.image_url||'')}' placeholder='./assets/servico.jpg'></label><label class='field wide'><span>Enviar imagem do dispositivo (JPG, PNG ou WebP; até 5 MB)</span><input name='image_file' type='file' accept='image/jpeg,image/png,image/webp'></label><label class='field'><span>Tipo de preço</span><select name='price_type'><option value='normal' ${type==='normal'?'selected':''}>Preço normal</option><option value='sale' ${type==='sale'?'selected':''}>De / por</option><option value='starting_at' ${type==='starting_at'?'selected':''}>A partir de</option><option value='consult' ${type==='consult'?'selected':''}>Sob consulta</option></select></label><label class='field' data-service-price='normal'><span>Preço normal</span><input name='price' type='number' min='0' step='0.01' value='${item?.price??0}'></label><label class='field' data-service-price='sale'><span>Preço anterior</span><input name='old_price' type='number' min='0' step='0.01' value='${item?.old_price??0}'></label><label class='field' data-service-price='sale'><span>Preço promocional</span><input name='promotional_price' type='number' min='0' step='0.01' value='${item?.promotional_price??0}'></label><label class='field' data-service-price='starting_at'><span>Valor “a partir de”</span><input name='starting_price' type='number' min='0' step='0.01' value='${item?.starting_price??0}'></label><label class='field'><span>Prazo</span><input name='duration_label' value='${escapeHtml(item?.duration_label||'')}' placeholder='1 a 3 dias'></label><label class='field wide'><span>Descrição</span><textarea name='description' rows='4'>${escapeHtml(item?.description||'')}</textarea></label><label class='field wide'><span>Benefícios (um por linha)</span><textarea name='benefits' rows='4' placeholder='Limpeza completa\nTroca de pasta térmica'>${escapeHtml(benefits)}</textarea></label><label class='field'><span>Ordem de exibição</span><input name='sort_order' type='number' min='0' value='${item?.sort_order??state.services.length}'></label><label class='check-field'><input name='active' type='checkbox' ${item?.active!==false?'checked':''}><span>Serviço ativo</span></label></div><div class='form-error'></div><div class='dialog-actions'><button type='button' class='secondary-action dialog-cancel'>Cancelar</button><button type='submit' class='admin-primary compact'>Salvar serviço</button></div></form>`,(event,close)=>saveService(event,item,close));
    const priceType=dialog.querySelector('[name=price_type]');
    const syncPriceFields=()=>dialog.querySelectorAll('[data-service-price]').forEach(field=>{field.hidden=field.dataset.servicePrice!==priceType.value;});
    priceType.onchange=syncPriceFields;syncPriceFields();
  }
  async function saveService(event,item,close){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const button=form.querySelector('[type="submit"]');const payload={name:data.get('name').trim(),model:data.get('model').trim(),image_url:data.get('image_url').trim()||null,icon:item?.icon||'⚙',price_type:data.get('price_type'),price:Number(data.get('price')||0),old_price:Number(data.get('old_price')||0),promotional_price:Number(data.get('promotional_price')||0),starting_price:Number(data.get('starting_price')||0),duration_label:data.get('duration_label').trim(),sort_order:Number(data.get('sort_order')||0),description:data.get('description').trim(),benefits:String(data.get('benefits')||'').split(/\r?\n|,/).map(value=>value.trim()).filter(Boolean),active:data.get('active')==='on'};button.disabled=true;try{const imageFile=data.get('image_file');if(imageFile&&imageFile.size)payload.image_url=await api().uploadImage(imageFile,'services');await api().request(item?`/rest/v1/services?id=eq.${item.id}`:'/rest/v1/services',{method:item?'PATCH':'POST',body:payload,headers:{Prefer:'return=minimal'}});close();await loadServices(true);api().toast(item?'Serviço atualizado':'Serviço cadastrado');}catch(error){form.querySelector('.form-error').textContent=error.message&&error.message!=='request_failed'?error.message:'Não foi possível salvar o serviço.';form.querySelector('.form-error').classList.add('show');button.disabled=false;}}
  async function toggleService(id,button){const item=state.services.find(row=>Number(row.id)===id);if(!item)return;button.disabled=true;try{await api().request(`/rest/v1/services?id=eq.${id}`,{method:'PATCH',body:{active:!item.active},headers:{Prefer:'return=minimal'}});item.active=!item.active;renderServices();api().toast('Serviço atualizado');}catch{button.disabled=false;api().toast('Não foi possível atualizar');}}
  async function deleteService(id,button){const item=state.services.find(row=>Number(row.id)===id);if(!item||!confirm(`Excluir o serviço “${item.name}${item.model?' '+item.model:''}”?`))return;button.disabled=true;try{await api().request(`/rest/v1/services?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadServices(true);api().toast('Serviço excluído');}catch{button.disabled=false;api().toast('Não foi possível excluir o serviço');}}
  async function loadServices(force=false){content().innerHTML=moduleSkeleton('SERVIÇOS');try{await Promise.all([fetchServices(),fetchServiceOrders()]);renderServices();if(force)api().toast('Serviços atualizados');}catch(error){moduleError('ATUALIZE O CATÁLOGO DE SERVIÇOS','Execute a migração admin-007-services-catalog.sql para liberar imagens, modelos e tipos de preço.',()=>loadServices(true),true);}}

  function renderOffers(){const needle=state.offerSearch.trim().toLocaleLowerCase('pt-BR');const offers=state.products.filter(item=>Number(item.discount)>0&&(!needle||[item.name,item.category,item.brand].some(value=>String(value||'').toLocaleLowerCase('pt-BR').includes(needle))));const average=offers.length?Math.round(offers.reduce((sum,item)=>sum+Number(item.discount),0)/offers.length):0;content().innerHTML=`<div class="module-head"><div><span class="module-kicker">CAMPANHAS</span><h2>Ofertas</h2><p>Transforme produtos do catálogo em promoções com preço e desconto consistentes.</p></div><button class="admin-primary compact" id="new-offer">＋ Criar oferta</button></div><div class="catalog-stats category-stats"><article class="catalog-stat"><small>OFERTAS ATIVAS</small><strong>${offers.length}</strong><span>produtos promocionais</span></article><article class="catalog-stat"><small>DESCONTO MÉDIO</small><strong>${average}%</strong><span>nas ofertas atuais</span></article><article class="catalog-stat"><small>ECONOMIA EXIBIDA</small><strong>${money(offers.reduce((sum,item)=>sum+Math.max(0,Number(item.old_price)-Number(item.price)),0))}</strong><span>soma por unidade</span></article></div><section class="admin-card catalog-panel"><div class="catalog-toolbar customers-toolbar"><label class="search-control"><span>⌕</span><input id="offer-search" type="search" placeholder="Buscar oferta" value="${escapeHtml(state.offerSearch)}"></label><span class="result-count">${offers.length} oferta${offers.length===1?'':'s'}</span></div>${offers.length?`<div class="offer-grid">${offers.map(item=>`<article class="offer-card"><div class="offer-thumb">${item.image_url?`<img src="${escapeHtml(assetUrl(item.image_url))}" alt="">`:escapeHtml(item.icon||'🎮')}</div><div><span>-${Number(item.discount)}%</span><h3>${escapeHtml(item.name)}</h3><small>${money(item.old_price)} por</small><strong>${money(item.price)}</strong></div><button class="table-action" data-offer-edit="${item.id}">Editar oferta</button></article>`).join('')}</div>`:'<div class="empty-state rich-empty"><span>％</span><strong>Nenhuma oferta ativa</strong><p>Escolha um produto e defina seu preço promocional.</p></div>'}</section>`;document.querySelector('#new-offer').onclick=()=>openOfferDialog();document.querySelector('#offer-search').oninput=event=>{state.offerSearch=event.target.value;renderOffers();document.querySelector('#offer-search')?.focus();};document.querySelectorAll('[data-offer-edit]').forEach(button=>button.onclick=()=>openOfferDialog(Number(button.dataset.offerEdit)));}
  function openOfferDialog(id=null){const item=id?state.products.find(row=>Number(row.id)===id):null;openDialog(`<form class="entity-form"><div class="dialog-head"><div><span class="module-kicker">PROMOÇÃO</span><h2>${item?'Editar oferta':'Criar oferta'}</h2></div><button type="button" class="dialog-close">×</button></div><div class="form-grid"><label class="field wide"><span>Produto</span><select name="product_id" required ${item?'disabled':''}><option value="">Selecione</option>${state.products.map(product=>`<option value="${product.id}" ${item&&Number(product.id)===Number(item.id)?'selected':''}>${escapeHtml(product.name)}</option>`).join('')}</select></label><label class="field"><span>Preço original</span><input name="old_price" type="number" min="0" step="0.01" value="${item?.old_price||item?.price||''}" required></label><label class="field"><span>Preço promocional</span><input name="price" type="number" min="0" step="0.01" value="${item?.price||''}" required></label></div><div class="form-error"></div><div class="dialog-actions">${item?'<button type="button" class="secondary-action remove-offer">Encerrar oferta</button>':''}<button type="button" class="secondary-action dialog-cancel">Cancelar</button><button type="submit" class="admin-primary compact">Salvar oferta</button></div></form>`,(event,close)=>saveOffer(event,item,close));const dialog=document.querySelector('dialog[open]')||document.querySelector('.admin-dialog:last-of-type');dialog?.querySelector('.remove-offer')?.addEventListener('click',()=>removeOffer(item,dialog));}
  async function saveOffer(event,item,close){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const product=item||state.products.find(row=>Number(row.id)===Number(data.get('product_id')));const oldPrice=Number(data.get('old_price'));const price=Number(data.get('price'));const error=form.querySelector('.form-error');if(!product||oldPrice<=price){error.textContent='O preço promocional precisa ser menor que o preço original.';error.classList.add('show');return}const discount=Math.max(1,Math.round((1-price/oldPrice)*100));const button=form.querySelector('[type="submit"]');button.disabled=true;try{await api().request(`/rest/v1/products?id=eq.${product.id}`,{method:'PATCH',body:{old_price:oldPrice,price,discount},headers:{Prefer:'return=minimal'}});close();await loadOffers(true);api().toast('Oferta salva');}catch{error.textContent='Não foi possível salvar a oferta.';error.classList.add('show');button.disabled=false;}}
  async function removeOffer(item,dialog){if(!item||!confirm(`Encerrar a oferta de “${item.name}”?`))return;try{await api().request(`/rest/v1/products?id=eq.${item.id}`,{method:'PATCH',body:{discount:0,old_price:item.price},headers:{Prefer:'return=minimal'}});dialog.close();dialog.remove();await loadOffers(true);api().toast('Oferta encerrada');}catch{api().toast('Não foi possível encerrar a oferta');}}
  async function loadOffers(force=false){content().innerHTML=moduleSkeleton('OFERTAS');try{await fetchProducts();renderOffers();if(force)api().toast('Ofertas atualizadas');}catch{moduleError('OFERTAS INDISPONÍVEIS','Não foi possível carregar os produtos promocionais.',()=>loadOffers(true));}}

  async function fetchBanners(){const rows=await api().request('/rest/v1/banners?select=*&order=sort_order.asc,created_at.desc');state.banners=Array.isArray(rows)?rows:[];return state.banners;}
  function renderBanners(){const active=state.banners.filter(item=>item.active).length;content().innerHTML=`<div class="module-head"><div><span class="module-kicker">VITRINE</span><h2>Banners</h2><p>Organize campanhas visuais e links promocionais da loja.</p></div><button class="admin-primary compact" id="new-banner">＋ Novo banner</button></div><div class="catalog-stats category-stats"><article class="catalog-stat"><small>TOTAL</small><strong>${state.banners.length}</strong><span>banners cadastrados</span></article><article class="catalog-stat"><small>ATIVOS</small><strong>${active}</strong><span>campanhas visíveis</span></article><article class="catalog-stat"><small>AGENDADOS</small><strong>${state.banners.filter(item=>item.starts_at&&new Date(item.starts_at)>new Date()).length}</strong><span>para publicação futura</span></article></div><section class="admin-card catalog-panel">${state.banners.length?`<div class="banner-list">${state.banners.map(item=>`<article class="banner-admin-card"><div class="banner-preview" style="${item.image_url?`background-image:linear-gradient(90deg,#071018cc,#07101844),url('${escapeHtml(assetUrl(item.image_url))}')`:''}"><span>${escapeHtml(item.eyebrow||'BLACKOUT')}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.subtitle||'')}</p></div><div class="banner-meta"><div><strong>Ordem ${Number(item.sort_order||0)}</strong><small>${item.active?'Ativo':'Inativo'}${item.starts_at?` • Início ${dateTime(item.starts_at)}`:''}</small></div><div><button class="visibility-toggle ${item.active?'on':''}" data-banner-toggle="${item.id}"><span></span>${item.active?'Ativo':'Inativo'}</button><button class="table-action" data-banner-edit="${item.id}">Editar</button><button class="table-action danger" data-banner-delete="${item.id}">Excluir</button></div></div></article>`).join('')}</div>`:'<div class="empty-state rich-empty"><span>▧</span><strong>Nenhum banner cadastrado</strong><p>Crie campanhas sem alterar o código da loja.</p></div>'}</section>`;document.querySelector('#new-banner').onclick=()=>openBannerDialog();document.querySelectorAll('[data-banner-edit]').forEach(button=>button.onclick=()=>openBannerDialog(Number(button.dataset.bannerEdit)));document.querySelectorAll('[data-banner-toggle]').forEach(button=>button.onclick=()=>toggleBanner(Number(button.dataset.bannerToggle),button));document.querySelectorAll('[data-banner-delete]').forEach(button=>button.onclick=()=>deleteBanner(Number(button.dataset.bannerDelete),button));}
  function openBannerDialog(id=null){const item=id?state.banners.find(row=>Number(row.id)===id):null;openDialog(`<form class="entity-form"><div class="dialog-head"><div><span class="module-kicker">CAMPANHA VISUAL</span><h2>${item?'Editar banner':'Novo banner'}</h2></div><button type="button" class="dialog-close">×</button></div><div class="form-grid"><label class="field"><span>Chamada curta</span><input name="eyebrow" value="${escapeHtml(item?.eyebrow||'')}"></label><label class="field"><span>Título</span><input name="title" value="${escapeHtml(item?.title||'')}" required></label><label class="field wide"><span>Texto de apoio</span><input name="subtitle" value="${escapeHtml(item?.subtitle||'')}"></label><label class="field wide"><span>Imagem (URL ou caminho)</span><input name="image_url" value="${escapeHtml(item?.image_url||'')}" placeholder="./assets/banner.png"></label><label class="field wide"><span>Enviar imagem do dispositivo (JPG, PNG ou WebP; até 5 MB)</span><input name="image_file" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="field"><span>Texto do botão</span><input name="link_label" value="${escapeHtml(item?.link_label||'Ver oferta')}"></label><label class="field"><span>Link do botão</span><input name="link_url" value="${escapeHtml(item?.link_url||'#offers')}"></label><label class="field"><span>Ordem</span><input name="sort_order" type="number" min="0" value="${item?.sort_order??state.banners.length}"></label><label class="check-field"><input name="active" type="checkbox" ${item?.active!==false?'checked':''}><span>Banner ativo</span></label><label class="field"><span>Início</span><input name="starts_at" type="datetime-local" value="${item?.starts_at?new Date(item.starts_at).toISOString().slice(0,16):''}"></label><label class="field"><span>Fim</span><input name="ends_at" type="datetime-local" value="${item?.ends_at?new Date(item.ends_at).toISOString().slice(0,16):''}"></label></div><div class="form-error"></div><div class="dialog-actions"><button type="button" class="secondary-action dialog-cancel">Cancelar</button><button type="submit" class="admin-primary compact">Salvar banner</button></div></form>`,(event,close)=>saveBanner(event,item,close));}
  async function saveBanner(event,item,close){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const button=form.querySelector('[type="submit"]');const payload={eyebrow:data.get('eyebrow').trim(),title:data.get('title').trim(),subtitle:data.get('subtitle').trim(),image_url:data.get('image_url').trim()||null,link_label:data.get('link_label').trim(),link_url:data.get('link_url').trim(),sort_order:Number(data.get('sort_order')||0),active:data.get('active')==='on',starts_at:data.get('starts_at')?new Date(data.get('starts_at')).toISOString():null,ends_at:data.get('ends_at')?new Date(data.get('ends_at')).toISOString():null};button.disabled=true;try{const imageFile=data.get('image_file');if(imageFile&&imageFile.size)payload.image_url=await api().uploadImage(imageFile,'banners');await api().request(item?`/rest/v1/banners?id=eq.${item.id}`:'/rest/v1/banners',{method:item?'PATCH':'POST',body:payload,headers:{Prefer:'return=minimal'}});close();await loadBanners(true);api().toast(item?'Banner atualizado':'Banner criado');}catch(error){form.querySelector('.form-error').textContent=error.message&&error.message!=='request_failed'?error.message:'Não foi possível salvar o banner.';form.querySelector('.form-error').classList.add('show');button.disabled=false;}}
  async function toggleBanner(id,button){const item=state.banners.find(row=>Number(row.id)===id);if(!item)return;button.disabled=true;try{await api().request(`/rest/v1/banners?id=eq.${id}`,{method:'PATCH',body:{active:!item.active},headers:{Prefer:'return=minimal'}});item.active=!item.active;renderBanners();api().toast('Banner atualizado');}catch{button.disabled=false;}}
  async function deleteBanner(id,button){const item=state.banners.find(row=>Number(row.id)===id);if(!item||!confirm(`Excluir o banner “${item.title}”?`))return;button.disabled=true;try{await api().request(`/rest/v1/banners?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadBanners(true);api().toast('Banner excluído');}catch{button.disabled=false;api().toast('Não foi possível excluir');}}
  async function loadBanners(force=false){content().innerHTML=moduleSkeleton('BANNERS');try{await fetchBanners();renderBanners();if(force)api().toast('Banners atualizados');}catch(error){moduleError('ATIVE O MÓDULO DE BANNERS','A estrutura de campanhas ainda não está disponível.',()=>loadBanners(true),error.status===404);}}

  const defaultSettings={id:1,store_name:'BLACKOUT Infor Games',support_phone:'(75) 9 8312-1210',whatsapp:'5575983121210',support_email:'',address:'Rua Nossa Senhora da Saúde, 432, Centro, Ribeira do Pombal - BA',business_hours:'Segunda a sábado, das 8h às 18h',instagram:'',delivery_fee:0,free_shipping_min:0,delivery_checkout_enabled:false,maintenance_mode:false};
  async function fetchSettings(){const rows=await api().request('/rest/v1/store_settings?select=*&id=eq.1');state.settings=Array.isArray(rows)&&rows[0]?rows[0]:{...defaultSettings};return state.settings;}
  function renderSettings(){const item={...defaultSettings,...state.settings};content().innerHTML=`<div class="module-head"><div><span class="module-kicker">LOJA</span><h2>Configurações</h2><p>Centralize contatos, endereço, entrega e disponibilidade da operação.</p></div><span class="date-chip">Alterações protegidas</span></div><form id="settings-form" class="settings-layout"><section class="admin-card settings-section"><div class="card-head"><div><h3>Identidade e atendimento</h3><span>Informações usadas pela equipe e pela vitrine.</span></div></div><div class="form-grid"><label class="field wide"><span>Nome da loja</span><input name="store_name" value="${escapeHtml(item.store_name)}" required></label><label class="field"><span>Telefone de atendimento</span><input name="support_phone" value="${escapeHtml(item.support_phone)}"></label><label class="field"><span>WhatsApp com DDD</span><input name="whatsapp" value="${escapeHtml(item.whatsapp)}"></label><label class="field"><span>E-mail de suporte</span><input name="support_email" type="email" value="${escapeHtml(item.support_email)}"></label><label class="field"><span>Instagram</span><input name="instagram" value="${escapeHtml(item.instagram)}" placeholder="@blackout"></label><label class="field wide"><span>Endereço</span><input name="address" value="${escapeHtml(item.address)}"></label><label class="field wide"><span>Horário de funcionamento</span><input name="business_hours" value="${escapeHtml(item.business_hours)}"></label></div></section><section class="admin-card settings-section"><div class="card-head"><div><h3>Entrega e operação</h3><span>Regras comerciais gerais.</span></div></div><div class="form-grid"><label class="field"><span>Taxa de entrega</span><input name="delivery_fee" type="number" min="0" step="0.01" value="${Number(item.delivery_fee||0)}"></label><label class="field"><span>Frete grátis a partir de</span><input name="free_shipping_min" type="number" min="0" step="0.01" value="${Number(item.free_shipping_min||0)}"></label><label class="check-field wide maintenance-check"><input name="delivery_checkout_enabled" type="checkbox" ${item.delivery_checkout_enabled?'checked':''}><span><strong>Habilitar entrega no checkout</strong><small>Use a taxa de entrega definida acima. Sem marcação, apenas retirada estará disponível.</small></span></label><label class="check-field wide maintenance-check"><input name="maintenance_mode" type="checkbox" ${item.maintenance_mode?'checked':''}><span><strong>Modo de manutenção</strong><small>Registra o estado operacional sem apagar produtos ou pedidos.</small></span></label></div><div class="settings-save"><span id="settings-status">As alterações ficam registradas no Supabase.</span><button type="submit" class="admin-primary compact">Salvar configurações</button></div></section></form>`;document.querySelector('#settings-form').onsubmit=saveSettings;}
  async function saveSettings(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const button=form.querySelector('[type="submit"]');const status=document.querySelector('#settings-status');const payload={id:1,store_name:data.get('store_name').trim(),support_phone:data.get('support_phone').trim(),whatsapp:phoneDigits(data.get('whatsapp')),support_email:data.get('support_email').trim(),address:data.get('address').trim(),business_hours:data.get('business_hours').trim(),instagram:data.get('instagram').trim(),delivery_fee:Number(data.get('delivery_fee')||0),free_shipping_min:Number(data.get('free_shipping_min')||0),delivery_checkout_enabled:data.get('delivery_checkout_enabled')==='on',maintenance_mode:data.get('maintenance_mode')==='on'};button.disabled=true;button.textContent='Salvando…';try{await api().request('/rest/v1/store_settings?on_conflict=id',{method:'POST',body:payload,headers:{Prefer:'resolution=merge-duplicates,return=minimal'}});state.settings=payload;status.textContent='Configurações salvas agora.';button.textContent='Salvo';api().toast('Configurações atualizadas');setTimeout(()=>{button.disabled=false;button.textContent='Salvar configurações';},1000);}catch{status.textContent='Não foi possível salvar. Verifique a migração operacional.';button.disabled=false;button.textContent='Salvar configurações';}}
  async function loadSettings(force=false){content().innerHTML=moduleSkeleton('CONFIGURAÇÕES');try{await fetchSettings();renderSettings();if(force)api().toast('Configurações atualizadas');}catch(error){moduleError('ATIVE AS CONFIGURAÇÕES','A tabela de configurações ainda não está disponível.',()=>loadSettings(true),error.status===404);}}

  window.BLACKOUT_ADMIN_OPERATIONS={loadOrders,loadCustomers,loadServices,loadOffers,loadBanners,loadSettings};
})();
